// ENGINE ONLY (feature `ovm-xver`; engine/HANDOVER.md step 2): a handover across OpenVM versions. The product
// guest's cross-version path (src/xver, RISC Zero's vendored recursion circuits) with the same three items, for an
// engine predecessor: the lineage entry's `verifier` is the SHA-256 PIN of the predecessor's verifying key file (agg
// vk + its baseline, bitcode), the key itself is embedded below (xver_keys.rs, generated by engine/guest/assemble.sh
// from HZ_OVM_XVER_KEYS), so this image's id commits to exactly those key bytes.
//
// `verify` establishes what `env::verify(image, journal)` would for a proof of the SAME VM: the predecessor's proof
// verifies under the pinned key (OpenVM's verifier, in software: engine/verify-core's verify_full_bytes, which also
// checks SHA-256(key) == pin, the image id recomputed from the key == `image`, and the proof's public values ==
// SHA-256(journal)). The key is pinned because OpenVM's verifier trusts the key it is given (engine/VERIFIER.md).
//
// The proof comes as input words after the aggregate's tail (main.rs reads n, then n words): word 0 = the proof's
// byte length, then its plain encoding (OpenVM's codec, no zstd) packed little-endian, zero-padded to a word.

mod keys {
    include!("xver_keys.rs");
}

fn eq32(a: &[u8; 32], b: &[u8; 32]) -> bool {
    let mut i = 0;
    while i < 32 {
        if a[i] != b[i] {
            return false;
        }
        i += 1;
    }
    true
}

/// The OpenVM version a carried key is of (keys::KEYS' third field): its proofs go to THAT version's verifier.
pub const V2_1_0: u8 = 0;
pub const V2_0_2: u8 = 1;

/// Is a predecessor with this key pin carried by this image? (main.rs asserts it at compile time for its lineage.)
pub const fn carried(v: &[u8; 32]) -> bool {
    let mut k = 0;
    while k < keys::KEYS.len() {
        let p = keys::KEYS[k].0;
        let mut i = 0;
        let mut same = true;
        while i < 32 {
            if p[i] != v[i] {
                same = false;
            }
            i += 1;
        }
        if same {
            return true;
        }
        k += 1;
    }
    false
}

pub mod accel {
    /// The product's xver takes a hash suite; the engine's verifier needs none.
    pub fn suite() {}
}

/// The predecessor's proof (`words`) of `journal` by image `image`, under the carried key whose pin is `verifier`.
pub fn verify(verifier: &[u8; 32], image: [u32; 8], journal: &[u8], words: &[u32], _suite: &()) -> Result<(), &'static str> {
    let (pin, key, version) = keys::KEYS.iter().find(|k| eq32(k.0, verifier)).ok_or("the predecessor's key is not carried by this image")?;
    let n = *words.first().ok_or("no predecessor proof given")? as usize;
    let bytes: alloc::vec::Vec<u8> = words[1..].iter().flat_map(|w| w.to_le_bytes()).collect();
    if n == 0 || n > bytes.len() || bytes.len() - n >= 4 {
        return Err("the predecessor proof's length does not match its words");
    }
    let id: alloc::vec::Vec<u8> = image.iter().flat_map(|w| w.to_le_bytes()).collect();
    // the predecessor's OWN verifier: a key file is that version's struct, its proof that version's encoding
    macro_rules! check {
        ($v:ident) => {
            $v::verify_full_bytes(key, *pin, &bytes[..n], journal, &id).map_err(|e| match e {
                $v::Refusal::VkPin => "the carried key is not its pin's",
                $v::Refusal::Image => "the predecessor proof's key is not the pinned image's",
                $v::Refusal::Journal => "the predecessor proof is not of this journal",
                $v::Refusal::Decode => "the predecessor proof does not decode",
                _ => "the predecessor proof does not verify",
            })
        };
    }
    match *version {
        V2_1_0 => check!(hazync_engine_verify),
        #[cfg(feature = "ovm-xver-v2_0_2")]
        V2_0_2 => check!(hazync_engine_verify_v2_0_2),
        _ => Err("the predecessor's OpenVM version is not built into this image"),
    }
}
